--
-- Name: v_latest_risk; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_latest_risk AS
 SELECT s.id AS spot_id,
    s.name,
    s.lat,
    s.lng,
    s.elevation_m,
    s.depression_depth_m,
    s.nearest_drain_m,
    s.notes,
    p.predicted_for,
    p.p_rain,
    p.p_actual,
    p.delta,
    p.risk_level,
    p.cause_label,
    p.dispatch_type,
    p.confidence_lower,
    p.confidence_upper,
    p.shap_top3
   FROM (public.flood_spots s
     LEFT JOIN LATERAL ( SELECT pr.id,
            pr.spot_id,
            pr.predicted_for,
            pr.p_rain,
            pr.p_actual,
            pr.delta,
            pr.risk_level,
            pr.cause_label,
            pr.dispatch_type,
            pr.confidence_lower,
            pr.confidence_upper,
            pr.shap_top3,
            pr.features,
            pr.created_at
           FROM public.predictions pr
          WHERE (pr.spot_id = s.id)
          ORDER BY (pr.predicted_for = '2025-07-15 10:30:00+00'::timestamp with time zone) DESC, pr.predicted_for DESC
         LIMIT 1) p ON (true))
  ORDER BY s.id;


